// src/components/FreelancerForm.js
import React, { useState } from 'react';
import '../index.css';

const FreelancerForm = () => {
  const [formData, setFormData] = useState({
    full_name: '',
    email: '',
    phone_number: '',
    gender: '',
    country: '',
    city: '',
    degree: '',
    experience_year: '',
    experience_level: '',
    hourly_rate: '',
    domain: '',
    work_preference: '',
    skills: '',
  });

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });
  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Freelancer Data:', formData);
    alert('Freelancer profile created!');
  };

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Freelancer Profile</h2>
        <form onSubmit={handleSubmit}>
          <input name="full_name" placeholder="Full Name" onChange={handleChange} required />
          <input name="email" type="email" placeholder="Email" onChange={handleChange} required />
          <input name="phone_number" placeholder="Phone Number" onChange={handleChange} required />
          <input name="country" placeholder="Country" onChange={handleChange} />
          <input name="city" placeholder="City" onChange={handleChange} />
          <input name="degree" placeholder="Degree" onChange={handleChange} />
          <input name="experience_year" placeholder="Experience (years)" onChange={handleChange} />
          <input name="experience_level" placeholder="Experience Level" onChange={handleChange} />
          <input name="hourly_rate" placeholder="Hourly Rate ($)" onChange={handleChange} />
          <input name="domain" placeholder="Domain" onChange={handleChange} />
          <input name="skills" placeholder="Skills (comma separated)" onChange={handleChange} />
          <select name="work_preference" onChange={handleChange}>
            <option value="">Select Work Preference</option>
            <option value="remote">Remote</option>
            <option value="onsite">Onsite</option>
          </select>
          <button type="submit" className="btn-primary">Submit</button>
        </form>
      </div>
    </div>
  );
};

export default FreelancerForm;
